const ids=['connection','connection-detail','open-deepseek','open-gemini','route-deepseek','route-gemini','answer-deepseek','answer-gemini','question','pip-question','pip-start','pip-image-note','pip-remove-image','image-input','auto-ocr','image-box','image-preview','remove-image','start','input-status','offline','ctrl-board','float','refresh-card','retry-card','back','stage','progress','progress-fill','progress-label','elapsed','model-progress','route-tabs','answer-tabs','original-section','original','view-image','copy-original','search-section','keywords','copy-keywords','sites','ask-answer','answer','copy-answer','error','pip-return','return-card','image-dialog','full-image','close-image'];
const ui=Object.fromEntries(ids.map(id=>[id,document.getElementById(id)]));
const local=location.hostname==='127.0.0.1'&&location.port==='8771',names={deepseek:'DeepSeek',gemini:'Gemini'};
let csrf='',image=null,session='',busy=false,pip=null,polling=false,routeSelected='',answerSelected='',modelData={deepseek:{},gemini:{}},startedAt=0,connectionState={},lastJob='';
const connecting=new Set();
const boardHome=ui['ctrl-board'].parentElement;
const chosen=prefix=>['deepseek','gemini'].filter(name=>ui[prefix+'-'+name].checked);
function stage(value){ui.stage.textContent=value;ui['input-status'].textContent=value;}
function error(value){ui.error.textContent=value;ui.error.hidden=!value;}
function controls(){ui.start.disabled=busy||!local;ui['ask-answer'].disabled=busy||!local||!session||!selectedOriginal();ui['refresh-card'].disabled=!local;ui['retry-card'].disabled=busy||!local||!lastJob;ui.question.disabled=busy;ui['pip-question'].disabled=busy||!local;ui['pip-start'].disabled=busy||!local;ui['pip-remove-image'].disabled=busy;ui['image-input'].disabled=busy;ui['auto-ocr'].disabled=busy;ui['remove-image'].disabled=busy;for(const prefix of ['route','answer'])for(const name of Object.keys(names))ui[prefix+'-'+name].disabled=busy;}
function selectedOriginal(){return modelData[routeSelected]?.original||Object.values(modelData).find(item=>item.original)?.original||'';}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Assistant-Session':csrf},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(body?.image?30000:path.startsWith('status?')?5000:18000)});let value;try{value=await response.json();}catch{throw new Error('本机服务未返回有效数据');}if(!response.ok)throw new Error(value.error||'本机请求失败');return value;}
async function copy(value){if(!value)return;try{await (pip?.document.hasFocus()?pip.navigator:navigator).clipboard.writeText(value);stage('已复制，可到检索网站粘贴。');}catch{const doc=pip?.document.hasFocus()?pip.document:document;const box=doc.createElement('textarea');box.value=value;doc.body.append(box);box.select();const ok=doc.execCommand('copy');box.remove();stage(ok?'已复制，可到检索网站粘贴。':'复制失败，请选中文字后按 Ctrl+C。');}}
function drawTabs(container,field,selected,setSelected){const available=Object.keys(names).filter(name=>modelData[name]?.[field]);container.hidden=available.length<2;container.replaceChildren(...available.map(name=>{const button=document.createElement('button');button.type='button';button.textContent=names[name];button.setAttribute('aria-pressed',String(name===selected));button.addEventListener('click',()=>{setSelected(name);draw();});return button;}));}
function draw(){const source=modelData[routeSelected]||{};const original=source.original||selectedOriginal();ui.original.textContent=original;ui['original-section'].hidden=!original;ui['view-image'].hidden=!image;const route=source.route;ui['search-section'].hidden=!route;ui.keywords.replaceChildren(...(route?.keywords||[]).map(word=>{const button=document.createElement('button');button.type='button';button.textContent=word;button.title='点击复制';button.addEventListener('click',()=>copy(word));return button;}));ui.sites.replaceChildren(...(route?.sites||[]).map(site=>{const card=document.createElement('div');card.className='site';const top=document.createElement('div');top.className='site-top';const link=document.createElement('a');link.href=site.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=site.name+' ↗';top.append(link);if(site.unlisted){const tag=document.createElement('span');tag.className='unlisted';tag.textContent='未收录';top.append(tag);}card.append(top);if(site.why){const why=document.createElement('p');why.textContent=site.why;card.append(why);}if(site.query){const query=document.createElement('div');query.className='query';query.textContent=site.query;const button=document.createElement('button');button.type='button';button.textContent='复制检索词';button.addEventListener('click',()=>copy(site.query));card.append(query,button);}return card;}));if(route&&!(route.sites||[]).length){const note=document.createElement('p');note.className='muted';note.textContent='模型未返回有效网站；可用上方关键词在素养聚合检索。';ui.sites.append(note);}const answer=modelData[answerSelected]?.answer||'';ui.answer.textContent=answer;ui.answer.hidden=!answer;ui['copy-answer'].hidden=!answer;drawTabs(ui['route-tabs'],'original',routeSelected,name=>{routeSelected=name;});drawTabs(ui['answer-tabs'],'answer',answerSelected,name=>{answerSelected=name;});controls();}
function mergeModels(result){for(const [name,value] of Object.entries(result.results||{})){if(!modelData[name])continue;for(const key of ['original','route','answer'])if(value[key])modelData[name][key]=value[key];if(value.route&&(!routeSelected||!modelData[routeSelected]?.route))routeSelected=name;if(value.original&&!routeSelected)routeSelected=name;if(value.answer&&(!answerSelected||!modelData[answerSelected]?.answer))answerSelected=name;}draw();}
function resetProgress(){startedAt=0;ui.elapsed.textContent='已用 0 秒';ui['progress-label'].textContent='准备提交';ui.progress.setAttribute('aria-valuenow','0');ui['progress-fill'].style.width='0%';ui['model-progress'].replaceChildren();}
function showProgress(result){startedAt=result.started_at||startedAt;const seconds=Math.max(0,Math.floor(Date.now()/1000-startedAt));ui.elapsed.textContent='已用 '+seconds+' 秒';const states=Object.values(result.results||{});const complete=states.filter(item=>item.state==='completed').length;let percentage=0;if(states.length){percentage=Math.round(states.map(item=>{if(item.state==='completed'||item.state==='failed')return 100;const text=item.stage||'';if(/同一对话|等待完整回复|已发送/.test(text))return 76;if(/原题已识别|关键词|网站/.test(text))return 55;if(/OCR|上传|识别/.test(text))return 28;return 15;}).reduce((a,b)=>a+b,0)/states.length);}ui.progress.setAttribute('aria-valuenow',String(percentage));ui['progress-fill'].style.width=percentage+'%';ui['progress-label'].textContent=result.state==='running'?`阶段进度 · ${complete}/${states.length} 已完成`:`${complete}/${states.length} 已完成`;ui['model-progress'].replaceChildren(...Object.entries(result.results||{}).map(([name,item])=>{const span=document.createElement('span');span.className=item.state==='failed'?'failed':'';span.textContent=names[name]+' · '+(item.state==='completed'?'完成':item.state==='failed'?'失败：'+(item.error||'请检查原窗口'):item.stage||'处理中');return span;}));}
function renderJob(result){mergeModels(result);showProgress(result);const stages=Object.entries(result.results||{}).map(([name,value])=>names[name]+'：'+(value.stage||value.state));stage(stages.join('；')||'模型正在处理…');if(result.state!=='running'){const errors=Object.entries(result.results||{}).filter(([,value])=>value.state==='failed').map(([name,value])=>names[name]+'：'+(value.error||'未完成'));error(errors.join('\n'));if(result.state==='failed')stage('所选模型均未完成；可以点击重试，先读取原对话。');}}
async function waitJob(id){if(polling)return;lastJob=id;sessionStorage.setItem('ctrl-last-job',id);polling=true;busy=true;controls();const deadline=Date.now()+240000;try{while(Date.now()<deadline){const result=await api('jobs/'+id);renderJob(result);if(result.state==='completed'||result.state==='failed'){sessionStorage.removeItem('ctrl-job');return;}await new Promise(resolve=>setTimeout(resolve,500));}throw new Error('等待超时；请先刷新任务状态，再尝试重试。');}catch(e){error(e.message);stage('读取任务中断；刷新会继续读取原任务，不会重复发送。');}finally{polling=false;busy=false;controls();refreshConnections().catch(()=>{});}}
ui['refresh-card'].addEventListener('click',async()=>{if(!local)return;ui['refresh-card'].disabled=true;try{if(lastJob){const result=await api('jobs/'+lastJob);renderJob(result);if(result.state==='running'&&!polling){sessionStorage.setItem('ctrl-job',lastJob);waitJob(lastJob);}else if(result.state!=='running')sessionStorage.removeItem('ctrl-job');}else if(session){const state=await api('ctrl/session?id='+encodeURIComponent(session));modelData=state.models;draw();stage('已刷新小窗内容；没有正在运行的任务。');}else stage('小窗已刷新；请放入题目开始识别。');}catch(e){error(e.message);stage('读取失败；可检查本机服务后再次刷新。');}finally{ui['refresh-card'].disabled=false;}});
ui['retry-card'].addEventListener('click',async()=>{if(!lastJob||busy)return;busy=true;controls();error('');stage('正在核对原任务与模型对话…');try{const job=await api('ctrl/retry',{job:lastJob,image});lastJob=job.id;sessionStorage.setItem('ctrl-last-job',job.id);sessionStorage.setItem('ctrl-job',job.id);await waitJob(job.id);}catch(e){error(e.message);stage('重试未开始；原结果仍保留。');}finally{busy=false;controls();}});
async function loadImage(file){if(busy)return;if(!file||!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024){error('只支持不超过 5 MB 的 PNG 或 JPEG 截图。');return;}image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});ui['image-preview'].src=image;ui['image-box'].hidden=false;ui['pip-image-note'].textContent='截图已载入';ui['pip-remove-image'].hidden=false;ui['view-image'].hidden=!selectedOriginal();error('');if(ui['auto-ocr'].checked&&local){stage('截图已载入，正在自动识别…');ui['pip-question'].blur();ui.start.click();}else{stage(local?'截图已载入，按 Enter 或点击“识别并建议”。':'截图已载入，请先启动本机助手。');(pip?ui['pip-question']:ui.start).focus({preventScroll:true});}}
ui['image-input'].addEventListener('change',event=>{if(event.target.files[0])loadImage(event.target.files[0]);});
ui.question.addEventListener('paste',event=>{const item=[...event.clipboardData.items].find(value=>['image/png','image/jpeg'].includes(value.type));if(item){event.preventDefault();loadImage(item.getAsFile());}});
ui.question.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.isComposing&&!event.shiftKey&&!event.ctrlKey&&!event.altKey&&!event.metaKey){event.preventDefault();if(!busy)ui.start.click();}});
ui.question.addEventListener('input',()=>{if(ui['pip-question'].value!==ui.question.value)ui['pip-question'].value=ui.question.value;});
ui['pip-question'].addEventListener('input',()=>{ui.question.value=ui['pip-question'].value;});
ui['pip-question'].addEventListener('paste',event=>{const item=[...event.clipboardData.items].find(value=>['image/png','image/jpeg'].includes(value.type));if(item){event.preventDefault();loadImage(item.getAsFile());}});
ui['pip-question'].addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.isComposing&&!event.shiftKey&&!event.ctrlKey&&!event.altKey&&!event.metaKey){event.preventDefault();if(!busy){ui['pip-question'].blur();ui.start.click();}}});
ui['pip-start'].addEventListener('click',()=>{ui['pip-question'].blur();ui.start.click();});ui['pip-remove-image'].addEventListener('click',()=>ui['remove-image'].click());
const pipCapture=ui['pip-question'].parentElement;
pipCapture.addEventListener('dragover',event=>{if([...(event.dataTransfer?.types||[])].includes('Files')){event.preventDefault();event.dataTransfer.dropEffect=busy?'none':'copy';pipCapture.classList.toggle('dragging',!busy);}});
pipCapture.addEventListener('dragleave',()=>pipCapture.classList.remove('dragging'));
pipCapture.addEventListener('drop',event=>{if(![...(event.dataTransfer?.types||[])].includes('Files'))return;event.preventDefault();pipCapture.classList.remove('dragging');if(!busy)loadImage(event.dataTransfer.files[0]);});
try{ui['auto-ocr'].checked=localStorage.getItem('ctrl-auto-ocr')!=='false';}catch{}
ui['auto-ocr'].addEventListener('change',()=>{try{localStorage.setItem('ctrl-auto-ocr',String(ui['auto-ocr'].checked));}catch{}});
ui['remove-image'].addEventListener('click',()=>{image=null;ui['image-input'].value='';ui['image-preview'].removeAttribute('src');ui['image-box'].hidden=true;ui['view-image'].hidden=true;ui['pip-image-note'].textContent='';ui['pip-remove-image'].hidden=true;});
document.addEventListener('dragover',event=>{if([...(event.dataTransfer?.types||[])].includes('Files')){event.preventDefault();event.dataTransfer.dropEffect=busy?'none':'copy';ui['ctrl-board'].classList.toggle('dragging',!busy);}});
document.addEventListener('drop',event=>{if(![...(event.dataTransfer?.types||[])].includes('Files'))return;event.preventDefault();ui['ctrl-board'].classList.remove('dragging');if(!busy)loadImage(event.dataTransfer.files[0]);});
document.addEventListener('dragleave',()=>ui['ctrl-board'].classList.remove('dragging'));
ui.start.addEventListener('click',async()=>{const text=ui.question.value.trim(),models=chosen('route');if(!models.length){error('至少选择一个识题模型。');return;}if(!text&&!image){error('请粘贴原题文字或截图。');return;}if(busy)return;modelData={deepseek:{},gemini:{}};routeSelected='';answerSelected='';session='';lastJob='';sessionStorage.removeItem('ctrl-last-job');draw();resetProgress();error('');stage(image?'正在识别截图原题…':'正在提取关键词和网站…');busy=true;controls();try{const job=await api('ctrl/start',{text,image,models});session=job.session;sessionStorage.setItem('ctrl-session',session);sessionStorage.setItem('ctrl-job',job.id);await waitJob(job.id);}catch(e){error(e.message);stage('未能开始，请检查本机助手和模型窗口。');}finally{busy=false;controls();}});
ui['ask-answer'].addEventListener('click',async()=>{const models=chosen('answer');if(!models.length){error('至少选择一个作答模型。');return;}if(!session||busy)return;busy=true;controls();error('');stage('正在询问所选模型答案…');try{const job=await api('ctrl/answer',{session,models});sessionStorage.setItem('ctrl-job',job.id);await waitJob(job.id);}catch(e){error(e.message);stage('询问答案未完成；不会自动重复发送。');}finally{busy=false;controls();}});
ui['copy-original'].addEventListener('click',()=>copy(selectedOriginal()));ui['copy-keywords'].addEventListener('click',()=>copy((modelData[routeSelected]?.route?.keywords||[]).join(' ')));ui['copy-answer'].addEventListener('click',()=>copy(modelData[answerSelected]?.answer||''));
ui['view-image'].addEventListener('click',()=>{if(!image)return;if(pip){const dialog=pip.document.createElement('dialog'),close=pip.document.createElement('button'),img=pip.document.createElement('img');dialog.id='image-dialog';img.id='full-image';close.textContent='关闭 ×';img.src=image;img.alt='题目原图';close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove());dialog.append(close,img);pip.document.body.append(dialog);dialog.showModal();}else{ui['full-image'].src=image;ui['image-dialog'].showModal();}});ui['close-image'].addEventListener('click',()=>ui['image-dialog'].close());
ui.back.addEventListener('click',()=>{pip?.close();window.focus();ui.question.scrollIntoView({behavior:'smooth',block:'center'});});ui['return-card'].addEventListener('click',()=>pip?.close());
ui.float.addEventListener('click',async()=>{if(pip){pip.close();return;}if(!window.documentPictureInPicture){error('此浏览器不支持置顶小窗；仍可复制原题、关键词和检索词。');return;}try{let expired=false;const opening=documentPictureInPicture.requestWindow({width:480,height:700});opening.then(win=>{if(expired)win.close();}).catch(()=>{});pip=await Promise.race([opening,new Promise((_,reject)=>setTimeout(()=>{expired=true;reject(new Error('timeout'));},6000))]);const style=pip.document.createElement('link');style.rel='stylesheet';style.href=document.querySelector('link[rel=stylesheet]').href;pip.document.head.append(style);pip.document.title='CTRL 检索卡片';pip.document.body.className='pip-body';pip.document.body.append(ui['ctrl-board']);ui['pip-question'].value=ui.question.value;controls();ui['pip-return'].hidden=false;ui.float.textContent='收回小窗';pip.addEventListener('pagehide',()=>{boardHome.prepend(ui['ctrl-board']);pip=null;ui['pip-return'].hidden=true;ui.float.textContent='置顶小窗 ↗';});}catch{pip=null;error('置顶小窗无法打开，请复制需要的内容或并排使用窗口。');}});
async function refreshConnections(){const statuses=await Promise.all(Object.keys(names).map(async name=>{try{return{name,...await api('status?model='+name)};}catch(e){return{name,status:'error',detail:e.message};}}));connectionState=Object.fromEntries(statuses.map(value=>[value.name,value.status]));ui.connection.textContent=statuses.map(value=>names[value.name]+(value.status==='ready'?' 已连接':value.status==='login_required'?' 需登录':' 未连接')).join(' · ');ui['connection-detail'].textContent=statuses.map(value=>value.detail||'').filter(Boolean).join('；');return connectionState;}
async function connectModel(name){if(!local||!csrf||connecting.has(name))return;connecting.add(name);ui['open-'+name].disabled=true;ui['connection-detail'].textContent='正在连接 '+names[name]+'…';try{const result=await api('browser/open',{model:name});ui['connection-detail'].textContent=(result.detail||names[name]+' 窗口已打开')+'；若尚未连接，请在模型窗口登录或验证后点击“连接 / 重连”。';setTimeout(async()=>{try{const state=await refreshConnections();if(state[name]!=='ready')ui['connection-detail'].textContent=names[name]+' 尚未就绪，请在模型窗口登录或验证后点击“连接 / 重连”。';}catch{}},2500);}catch(e){ui['connection-detail'].textContent=names[name]+' 自动连接失败：'+e.message+'。可点击“连接 / 重连”重试。';}finally{connecting.delete(name);ui['open-'+name].disabled=false;}}
for(const name of Object.keys(names)){ui['open-'+name].addEventListener('click',()=>connectModel(name));ui['route-'+name].addEventListener('change',()=>{if(ui['route-'+name].checked&&connectionState[name]!=='ready')connectModel(name);});}
async function init(){if(!local){ui.offline.hidden=false;ui.connection.textContent='静态预览';controls();return;}try{const response=await fetch('/api/session',{cache:'no-store'});if(!response.ok)throw new Error('本机服务不可用');csrf=(await response.json()).session;await refreshConnections();const saved=sessionStorage.getItem('ctrl-session');if(saved){try{const state=await api('ctrl/session?id='+encodeURIComponent(saved));session=saved;modelData=state.models;routeSelected=Object.keys(names).find(name=>modelData[name]?.route)||Object.keys(names).find(name=>modelData[name]?.original)||'';answerSelected=Object.keys(names).find(name=>modelData[name]?.answer)||'';draw();stage('已恢复本机 CTRL 会话。');if(Object.values(modelData).some(value=>value.route||value.answer)){ui.elapsed.textContent='上次结果';ui['progress-label'].textContent='已恢复';ui.progress.setAttribute('aria-valuenow','100');ui['progress-fill'].style.width='100%';}}catch{sessionStorage.removeItem('ctrl-session');}}lastJob=sessionStorage.getItem('ctrl-last-job')||'';const job=sessionStorage.getItem('ctrl-job');if(job)await waitJob(job);else if(lastJob){try{renderJob(await api('jobs/'+lastJob));}catch{stage('已恢复本页内容；原任务可能已过期。');}}for(const name of chosen('route'))if(connectionState[name]!=='ready')connectModel(name);}catch(e){ui.connection.textContent='本机服务未连接';ui['connection-detail'].textContent=e.message+'。请重新启动本机助手；模型重连按钮会保留。';ui.offline.hidden=false;}controls();}
init();
